// Generated by anvil.kit.blocks.wood_set. Edits are overwritten on the next build.
import { StartupEvent, world } from "@minecraft/server";
import { registerSupportComponent, registerSupportEvents } from "./support";
import { registerTogglableComponent } from "./togglable";
import { registerInteractableComponent } from "./interactable";
import { registerDoorComponent } from "./door";
import { registerRedstoneConsumerComponent } from "./redstone-consumer";
import { registerStrippableComponent, registerStrippableEvents } from "./strippable";
import { registerSlabComponent, registerSlabEvents } from "./slab";
import { registerSignComponent } from "./sign";
import { registerLeavesComponent } from "./leaves";
import { registerSaplingComponent } from "./sapling";
import { registerBoatEvents } from "./boat";

// Single entry point: call once from `system.beforeEvents.startup`.
export function registerWoodSet(init: StartupEvent): void {
	registerSupportComponent(init);
	registerTogglableComponent(init);
	registerInteractableComponent(init);
	registerDoorComponent(init);
	registerRedstoneConsumerComponent(init);
	registerStrippableComponent(init);
	registerSlabComponent(init);
	registerSignComponent(init);
	registerLeavesComponent(init);
	registerSaplingComponent(init);

	// World events can't be subscribed during startup, so they wait for world load.
	world.afterEvents.worldLoad.subscribe(() => {
		registerSupportEvents();
		registerStrippableEvents();
		registerSlabEvents();
		registerBoatEvents();
	});
}
